use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let path_str = input.as_str().unwrap();
    let mut ancestors = Vec::new();
    let mut current_path = String::new();

    for c in path_str.chars() {
        current_path.push(c);
        if c == '/' {
            ancestors.push(json!(current_path));
        }
    }

    if !current_path.is_empty() {
        ancestors.push(json!(current_path));
    }

    json!(ancestors)
}
